import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import {
  ArrayMinSize,
  IsArray,
  IsEnum,
  IsInt,
  IsNotEmpty,
  IsObject,
  IsOptional,
  IsString,
  IsUUID,
  MaxLength,
  Min,
} from 'class-validator';
import { PageQueryDto } from '../forecasting/dto.js';
import { InventoryImportStatus } from '../generated/prisma/tenant/enums.js';

export class CreateInventoryImportDto {
  @ApiProperty({
    format: 'uuid',
    example: '6f1c2d4e-8a7b-4c1d-9e2f-3a4b5c6d7e8f',
    description:
      'Generated by the frontend once per file. Sending the same request again ' +
      'returns the same import; the same id with another body is rejected',
  })
  @IsUUID()
  clientRequestId: string;

  @ApiProperty({ example: 1, description: 'Row format version; only 1' })
  @IsInt()
  @Min(1)
  schemaVersion: number;

  @ApiProperty({
    example: 'inventario-noviembre.xlsx',
    description: "Name of the user's file, for display only",
  })
  @IsString()
  @IsNotEmpty()
  @MaxLength(255)
  fileName: string;

  @ApiProperty({
    example: 'Inventario',
    description: 'Sheet read, for display only',
  })
  @IsString()
  @IsNotEmpty()
  @MaxLength(100)
  sheetName: string;

  @ApiProperty({
    example: 4800,
    description:
      'Non-empty data rows of the sheet (no header, no blank rows). Above the ' +
      'limit of `GET /inventory-imports/fields` the import is refused',
  })
  @IsInt()
  @Min(1)
  totalRows: number;

  @ApiProperty({
    type: 'object',
    additionalProperties: {
      type: 'object',
      nullable: true,
      properties: {
        column: { type: 'integer', minimum: 1, example: 1 },
        header: { type: 'string', example: 'Código producto *' },
      },
    },
    description:
      'For each field key, the column of the file (1 = A) and its header, or ' +
      'null when the file lacks it. Stored for traceability; the seven required ' +
      'fields must be mapped and a column may feed only one field',
    example: {
      sku: { column: 1, header: 'Código producto *' },
      name: { column: 2, header: 'Producto *' },
      category: { column: 3, header: 'Categoría *' },
      stockUnit: { column: 4, header: 'Unidad de medida *' },
      warehouse: { column: 5, header: 'Bodega *' },
      tracksLots: { column: 6, header: 'Seguimiento *' },
      stockQuantity: { column: 7, header: 'Saldo inicial *' },
      unitCost: { column: 8, header: 'Costo unitario' },
      lotCode: null,
    },
  })
  @IsObject()
  mapping: Record<string, unknown>;
}

export class ListInventoryImportsQueryDto extends PageQueryDto {
  @ApiPropertyOptional({
    enum: InventoryImportStatus,
    enumName: 'InventoryImportStatus',
  })
  @IsOptional()
  @IsEnum(InventoryImportStatus)
  status?: InventoryImportStatus;
}

/** Documentation of one sent row (the service checks the shape itself). */
class InventoryImportRowDto {
  @ApiProperty({
    example: 2,
    description:
      "Row of the user's file, the header being row 1; unique in the import",
  })
  rowNumber: number;

  @ApiProperty({
    type: 'object',
    additionalProperties: { type: 'string', nullable: true },
    description:
      'Field key → the cell as text, or null when empty. Only dictionary keys. ' +
      'Decimals with "." and no thousands separator, dates YYYY-MM-DD',
    example: {
      sku: 'TOR-001',
      name: 'Tornillo',
      category: 'Tornillería',
      stockUnit: 'Unidad',
      warehouse: 'Principal',
      tracksLots: 'Cantidad',
      stockQuantity: '500',
      unitCost: '350',
    },
  })
  values: Record<string, string | null>;
}

export class AppendInventoryRowsDto {
  @ApiProperty({
    example: 1,
    description:
      'Chosen by the frontend, from 1; batches may arrive in any order. The same ' +
      'number with the same rows is a retry',
  })
  @IsInt()
  @Min(1)
  batchNumber: number;

  @ApiProperty({
    type: [InventoryImportRowDto],
    description:
      'From 1 to `limits.maxRowsPerBatch` rows, and the whole body within ' +
      '`limits.maxRequestBytes`',
  })
  @IsArray()
  @ArrayMinSize(1)
  rows: unknown[];
}
